WITH valid AS (SELECT id, plan, start_date, status, ADD_MONTHS(start_date, 1) AS start_date_plus_months FROM subscriptions WHERE start_date > DATE '2023-03-14'), metrics AS (SELECT *, ROW_NUMBER() OVER w_hist AS seq_no, ROW_NUMBER() OVER w_hist AS seq_no_2, ROW_NUMBER() OVER w_hist_2 AS event_seq FROM valid WHERE start_date >= '2023-10-01' WINDOW w_hist AS (PARTITION BY plan ORDER BY start_date_plus_months DESC, id), w_hist_2 AS (PARTITION BY plan ORDER BY start_date DESC, id)), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, plan ORDER BY start_date NULLS FIRST, id) AS dedup_rank FROM metrics QUALIFY dedup_rank = 1), filtered AS (SELECT *, DATE_FORMAT(start_date, 'yyyy-MM') AS start_date_label, seq_no_2 * seq_no AS seq_no_2_times_seq_no FROM ranked WHERE status IN ('EXPIRED', 'ACTIVE', 'CANCELLED')), metrics_subscriptions AS (SELECT *, AVG(seq_no) OVER w_grp AS seq_no_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY plan, status ORDER BY seq_no_2, id) AS seq_no_3 FROM filtered WINDOW w_grp AS (PARTITION BY plan ORDER BY start_date_plus_months, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING)) SELECT seq_no, COUNT(*) FILTER (WHERE plan = 'enterprise') AS enterprise_rows, COUNT(DISTINCT plan) AS distinct_plans, SUM(CASE WHEN plan = 'enterprise' THEN event_seq ELSE 0 END) AS enterprise_event_seq FROM metrics_subscriptions GROUP BY ROLLUP (seq_no) HAVING enterprise_rows > 1;
